12	export default async function BrowsePage({
13	  searchParams,
14	}: {
15	  searchParams: Promise<Record<string, string | undefined>>;
16	}) {
17	  const sp = await searchParams;
18	  const maxPrice = sp.maxPrice ? Number(sp.maxPrice) : undefined;
19	
20	  const profile = await getProfile();
21	  const isCustomer = profile?.role === "customer";
22	
23	  const [providers, favoriteIds] = await Promise.all([
24	    listApprovedProviders({
25	      topic: sp.topic || undefined,
26	      language: sp.language || undefined,
27	      availableNow: sp.available === "1" || undefined,
28	      maxPriceCents:
29	        typeof maxPrice === "number" && Number.isFinite(maxPrice)
30	          ? maxPrice
31	          : undefined,
32	    }),
33	    isCustomer ? listFavoriteIds(profile.id) : Promise.resolve([]),
34	  ]);
35	  const favoriteSet = new Set(favoriteIds);
36	
37	  const withAudio = await Promise.all(
38	    providers.map(async (provider) => ({
39	      provider,
40	      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
41	    })),
42	  );
43	
44	  return (
45	    <div className="flex flex-col gap-6">
46	      <div className="flex flex-col gap-1.5">
47	        <h1 className="text-h1">{t("browse.title")}</h1>
48	        <p className="text-lg text-ink-soft">{t("browse.subtitle")}</p>
49	      </div>
50	
51	      <Suspense fallback={null}>
52	        <BrowseFilters />
53	      </Suspense>
54	
55	      <p className="text-base font-bold text-ink-soft" aria-live="polite">
56	        {t("browse.resultsCount", { count: providers.length })}
57	      </p>
58	
59	      {withAudio.length === 0 ? (
60	        <Card>
61	          <p className="text-base text-ink-soft">{t("browse.noResults")}</p>
62	        </Card>
63	      ) : (
64	        <ul className="grid grid-cols-2 gap-5 max-md:grid-cols-1">
65	          {withAudio.map(({ provider, audioUrl }) => (
66	            <ListenerCard
67	              key={provider.id}
68	              provider={provider}
69	              audioUrl={audioUrl}
70	              canFavorite={isCustomer}
71	              isFavorite={favoriteSet.has(provider.id)}
72	            />
73	          ))}
74	        </ul>
75	      )}
76	    </div>
77	  );
78	}
